import CustomImage from "@/components/molecules/customImage"
import { cn } from "@/lib/utils"
import React from "react"

const VerifiedBadge = ({
  position= "default",
  className,
  size,
  verified,
}) => {
  const positionClasses = {
    "default" : "rounded-tl-2xl bottom-0 right-0",
    "top-left" : "top-0 left-0",
    "top-right" : "top-0 right-0",
    "bottom-left" : "bottom-0 left-0",
  }
  return (
    <div className={cn(
      "absolute flex items-center justify-center gap-2 px-3 py-1 bg-[#016a55aa]",
      positionClasses[position],
      className={className}
    )}>
      <div className={cn("size-7", size)}>
        <CustomImage
          imageSrc="/images/icon/rocksport.svg"
          width={1000}
          height={1000}
          className="responsive-image-contain"
        />
      </div>
      <span className="text-white">{verified}</span>
    </div>
  )
}

export default VerifiedBadge
